#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<long long> a(n), result(n);
    for (auto& x : a) cin >> x;
    int lo = 0, hi = n - 1;
    for (int pos = n - 1; pos >= 0; pos--) {  // the largest square is at one of the ends
        if (llabs(a[lo]) > llabs(a[hi])) { result[pos] = a[lo] * a[lo]; lo++; }
        else { result[pos] = a[hi] * a[hi]; hi--; }
    }
    for (int i = 0; i < n; i++) cout << result[i] << (i + 1 < n ? " " : "\n");
    return 0;
}

