#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    long long target;
    cin >> n >> target;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    sort(a.begin(), a.end());
    long long best = a[0] + a[1] + a[2];
    for (int i = 0; i + 2 < n; i++) {
        int lo = i + 1, hi = n - 1;
        while (lo < hi) {
            long long s = a[i] + a[lo] + a[hi];
            if (make_pair(llabs(s - target), s) < make_pair(llabs(best - target), best)) best = s;
            if (s < target) lo++;
            else if (s > target) hi--;
            else break;
        }
    }
    cout << best << "\n";
    return 0;
}

